(function(){"use strict";document.querySelectorAll('#navbarResponsive .nav-link').forEach(function(l){l.addEventListener('click',function(){var c=document.getElementById('navbarResponsive');if(c&&c.classList.contains('show')){var b=bootstrap.Collapse.getInstance(c);if(b)b.hide();}});});function s(){var n=document.getElementById('mainNav');if(!n)return;n.classList.toggle('navbar-shrink',window.scrollY>100);}s();window.addEventListener('scroll',s,{passive:true});})();
